// Extrai e formata os leads recebidos do Agência Ninja Scraper
const payload = $input.first().json.body || $input.first().json;
const leads = payload.leads || [];
const jobName = payload.job_name || 'Coleta Ninja';
const timestamp = payload.timestamp || new Date().toISOString();

const enrichedLeads = leads.map((lead, idx) => {
  const rawPhone = String(lead.phone || '').replace(/\D/g, '');
  let cleanPhone = rawPhone;
  if (cleanPhone.startsWith('55') && cleanPhone.length >= 12) {
    cleanPhone = cleanPhone.slice(2);
  }

  const isMobile = cleanPhone.length === 11 && cleanPhone[2] === '9';
  const waNumber = isMobile ? `55${cleanPhone}` : '';

  return {
    json: {
      id: idx + 1,
      job_name: jobName,
      received_at: timestamp,
      empresa: lead.title || '',
      categoria: lead.category || '',
      telefone: lead.phone || '',
      telefone_limpo: cleanPhone,
      whatsapp_valido: isMobile,
      whatsapp_numero: waNumber,
      email: lead.emails || '',
      website: lead.website || '',
      nota: parseFloat(lead.review_rating) || 0,
      avaliacoes: parseInt(lead.review_count) || 0,
      endereco: lead.address || '',
      maps_link: lead.link || '',
      instagram: lead.instagram || '',
      facebook: lead.facebook || '',
      linkedin: lead.linkedin || '',
      mensagem_abordagem: `Olá! Sou da Agência Ninja. Estive analisando o perfil da empresa ${lead.title || ''} no Google Maps e identifiquei excelentes oportunidades para escalar a captação de clientes de vocês com IA e automação.`
    }
  };
});

return enrichedLeads;
